window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c5597403d6290cf"]={"versions": [{"id": "FIG-5c5597403d6290cf", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb des E2E-Profils 7 (E2E Profile 7). Das Diagramm stellt den Teilschritt „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P07Protect()</code> dar, eingebettet in die AUTOSAR-E2E-Bibliothek zur sicherheitsgerichteten Datenübertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionskontext: <code>E2E_P07Protect()</code>\n</li><li>Eingangsparameter / Entitäten:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die Konfigurationsstruktur des E2E-Profils 7 (enthält Grenzwerte <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits)\n</li><li><code>State</code>: Zeiger auf den Zustandsvektor der Schutzfunktion\n</li><li><code>Data</code>: Zeiger auf das Nutzdaten-Array / Payload\n</li><li><code>Length</code>: Länge der Nutzdaten in Bytes\n</li></ul>\n</li><li>Kontrollflusselemente &amp; Endzustände:\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Zwei Entscheidungsknoten (Decision Nodes)\n</li><li>Drei Aktivitätsendknoten (Activity Final Nodes) mit den Zustandsausgängen <code>null input</code>, <code>input ok</code> und <code>wrong input</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und führt zum ersten Entscheidungsknoten.\n</li><li>Im ersten Entscheidungsknoten wird geprüft: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.\n<ul class=\"fig-list\"><li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Pfad nach links ab und terminiert im Endzustand <code>null input</code>.\n</li><li>Ergibt die Bedingung <code>[TRUE]</code>, setzt sich der Kontrollfluss zum zweiten Entscheidungsknoten fort.\n</li></ul>\n</li><li>Im zweiten Entscheidungsknoten wird geprüft, ob die Datenlänge innerhalb der parametrierten Schranken liegt: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code>.\n<ul class=\"fig-list\"><li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Pfad nach rechts ab und terminiert im Endzustand <code>wrong input</code>.\n</li><li>Ergibt die Bedingung <code>[TRUE]</code>, führt der Kontrollfluss direkt in den regulären Endzustand <code>input ok</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Prüfverhalten gemäß Anforderung <code>[PRS_E2E_00487]</code>. Implementierende Softwarekomponenten müssen vor Beginn der Schutzoperationen sicherstellen, dass alle Zeiger ungleich <code>NULL</code> sind (Fehlerfall führt zu Rückgabewert bzw. Fehlerbehandlung für Null-Zeiger) und dass die übergebene Bytelänge mit den konfigurierten Bitlängen geteilt durch 8 (<code>MinDataLength/8</code>, <code>MaxDataLength/8</code>) konsistent ist (Fehlerfall führt zu Beendigung wegen fehlerhafter Datenlänge). Nur bei erfolgreicher Prüfung (<code>input ok</code>) darf mit den nachfolgenden Schritten von <code>E2E_P07Protect()</code> fortgefahren werden.</p>"}, {"id": "FIG-fbe10e23b990c6c4", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb des E2E-Profils 7 (E2E Profile 7). Das Diagramm stellt den Teilschritt „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P07Protect()</code> dar, eingebettet in die AUTOSAR-E2E-Bibliothek zur sicherheitsgerichteten Datenübertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionskontext: <code>E2E_P07Protect()</code>\n</li><li>Eingangsparameter / Entitäten:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die Konfigurationsstruktur des E2E-Profils 7 (enthält Grenzwerte <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits)\n</li><li><code>State</code>: Zeiger auf den Zustandsvektor der Schutzfunktion\n</li><li><code>Data</code>: Zeiger auf das Nutzdaten-Array / Payload\n</li><li><code>Length</code>: Länge der Nutzdaten in Bytes\n</li></ul>\n</li><li>Kontrollflusselemente &amp; Endzustände:\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Zwei Entscheidungsknoten (Decision Nodes)\n</li><li>Drei Aktivitätsendknoten (Activity Final Nodes) mit den Zustandsausgängen <code>null input</code>, <code>input ok</code> und <code>wrong input</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und führt zum ersten Entscheidungsknoten.\n</li><li>Im ersten Entscheidungsknoten wird geprüft: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.\n<ul class=\"fig-list\"><li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Pfad nach links ab und terminiert im Endzustand <code>null input</code>.\n</li><li>Ergibt die Bedingung <code>[TRUE]</code>, setzt sich der Kontrollfluss zum zweiten Entscheidungsknoten fort.\n</li></ul>\n</li><li>Im zweiten Entscheidungsknoten wird geprüft, ob die Datenlänge innerhalb der parametrierten Schranken liegt: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code>.\n<ul class=\"fig-list\"><li>Ergibt die Bedingung <code>[FALSE]</code>, zweigt der Pfad nach rechts ab und terminiert im Endzustand <code>wrong input</code>.\n</li><li>Ergibt die Bedingung <code>[TRUE]</code>, führt der Kontrollfluss direkt in den regulären Endzustand <code>input ok</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Prüfverhalten gemäß Anforderung <code>[PRS_E2E_00487]</code>. Implementierende Softwarekomponenten müssen vor Beginn der Schutzoperationen sicherstellen, dass alle Zeiger ungleich <code>NULL</code> sind (Fehlerfall führt zu Rückgabewert bzw. Fehlerbehandlung für Null-Zeiger) und dass die übergebene Bytelänge mit den konfigurierten Bitlängen geteilt durch 8 (<code>MinDataLength/8</code>, <code>MaxDataLength/8</code>) konsistent ist (Fehlerfall führt zu Beendigung wegen fehlerhafter Datenlänge). Nur bei erfolgreicher Prüfung (<code>input ok</code>) darf mit den nachfolgenden Schritten von <code>E2E_P07Protect()</code> fortgefahren werden.</p>"}], "trans": [{"from": "FIG-5c5597403d6290cf", "to": "FIG-fbe10e23b990c6c4", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
